command:
php -n -r '
foreach (["fgetcsv","fputcsv","str_getcsv"] as $f) {
  $r = new ReflectionFunction($f);
  $ps = [];
  foreach ($r->getParameters() as $p) {
    $t = $p->getType() ? (string)$p->getType() : "";
    $d = "";
    if ($p->isDefaultValueAvailable()) { $d = " = " . str_replace(PHP_EOL,"",var_export($p->getDefaultValue(), true)); }
    elseif ($p->isOptional()) { $d = " = <unknown>"; }
    $ps[] = trim("$t \$" . $p->getName() . $d);
  }
  echo $f . "(" . implode(", ", $ps) . "): " . ($r->getReturnType() ?: "?") . "\n";
}
'
